    def to_float_strict(x):
        if isinstance(x, str):
            # Replace comma with dot for float conversion
            return float(x.replace(',', '.'))
        elif isinstance(x, (int, float)):
            return float(x)
        else:
            raise ValueError("Unsupported type")

