def encrypt(s):
    result = []
    for char in s:
        # Shift only lowercase letters
        if 'a' <= char <= 'z':
            shifted = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
            result.append(shifted)
        # Shift only uppercase letters if needed, else keep as is
        elif 'A' <= char <= 'Z':
            shifted = chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
            result.append(shifted)
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)
    return ''.join(result)
