def get_maxgold(grid):
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])
    # dp[i][j] will store max gold collected starting from cell (i,j)
    dp = [[0]*n for _ in range(m)]

    # Fill dp from right to left
    for j in range(n-1, -1, -1):
        for i in range(m):
            if j == n-1:
                dp[i][j] = grid[i][j]
            else:
                right = dp[i][j+1] if 0 <= i < m else 0
                right_up = dp[i-1][j+1] if i-1 >= 0 else 0
                right_down = dp[i+1][j+1] if i+1 < m else 0
                dp[i][j] = grid[i][j] + max(right, right_up, right_down)

    # Since start is restricted to (0,0)
    return dp[0][0]
```

