def set_left_most_unset_bit(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    # Find the position of the highest set bit
    highest_bit_pos = n.bit_length() - 1

    # Check bits from highest_bit_pos down to 0 for the leftmost unset bit
    for pos in range(highest_bit_pos, -1, -1):
        if (n & (1 << pos)) == 0:
            return n | (1 << pos)

    # If all bits up to highest_bit_pos are set, check the next higher bit
    # This means we add a new bit at position highest_bit_pos + 1
    # But per clarification, only set existing unset bits, so return n unchanged
    return n
