def find_even_Pair(arr):
    count_even = 0
    count_odd = 0
    for num in arr:
        if num % 2 == 0:
            count_even += 1
        else:
            count_odd += 1
    # XOR of two numbers is even if both numbers have the same parity (both even or both odd)
    return count_even * (count_even - 1) // 2 + count_odd * (count_odd - 1) // 2
